<template><div class="shell"><aside :class="{mini:collapsed}"><div class="brand"><div class="brand-icon"><el-icon><Reading/></el-icon></div><div v-if="!collapsed"><b>云图书馆</b><small>LIBRARY CLOUD</small></div></div><el-menu router :default-active="$route.path" background-color="transparent" text-color="#afbdd0" active-text-color="#fff" :collapse="collapsed"><el-menu-item v-for="m in menus" :key="m.path" :index="m.path"><el-icon><component :is="m.icon"/></el-icon><template #title>{{m.title}}</template></el-menu-item></el-menu><div class="aside-foot" v-if="!collapsed"><div class="status-dot"></div>微服务运行正常</div></aside><main><header><el-button text circle @click="collapsed=!collapsed"><el-icon size="20"><Fold v-if="!collapsed"/><Expand v-else/></el-icon></el-button><div class="crumb">工作台 <span>/</span> {{$route.meta.title}}</div><div class="header-right"><el-badge :value="3"><el-button circle text><el-icon><Bell/></el-icon></el-button></el-badge><div class="user"><el-avatar :size="36">{{user.realName?.slice(0,1)||'管'}}</el-avatar><div><b>{{user.realName||'系统管理员'}}</b><small>{{roleName}}</small></div></div><el-dropdown @command="logout"><el-button circle text><el-icon><ArrowDown/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="logout">退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header><section class="content"><router-view/></section></main></div></template>
<script setup lang="ts">import{ref,computed}from'vue';import{useRouter}from'vue-router';const collapsed=ref(false);const router=useRouter();const user=JSON.parse(localStorage.getItem('user')||'{}');const roleName=computed(()=>({ADMIN:'系统管理员',LIBRARIAN:'图书管理员',READER:'读者'} as any)[user.roleCode]||'系统管理员');const menus=[{path:'/dashboard',title:'数据总览',icon:'DataBoard'},{path:'/books',title:'图书管理',icon:'Notebook'},{path:'/categories',title:'分类管理',icon:'CollectionTag'},{path:'/readers',title:'读者管理',icon:'User'},{path:'/borrows',title:'借阅管理',icon:'Switch'},{path:'/reservations',title:'预约管理',icon:'Calendar'},{path:'/announcements',title:'公告管理',icon:'Bell'},{path:'/rules',title:'借阅规则',icon:'Setting'},{path:'/users',title:'用户管理',icon:'UserFilled'},{path:'/profile',title:'个人中心',icon:'Avatar'}];function logout(){localStorage.clear();router.push('/login')}</script>
<style scoped>.shell{display:flex;min-height:100vh}aside{width:238px;background:linear-gradient(180deg,#13283f,#173a54);padding:22px 14px;position:fixed;inset:0 auto 0 0;transition:.2s;z-index:2}aside.mini{width:68px}.brand{height:62px;display:flex;gap:12px;align-items:center;padding:0 8px 18px;color:#fff}.brand-icon{width:38px;height:38px;display:grid;place-items:center;border-radius:12px;background:linear-gradient(135deg,#44c59a,#2c9b7b);font-size:20px}.brand b{display:block;font-size:18px}.brand small{font-size:9px;letter-spacing:1.5px;color:#7fa7b6}.el-menu{border:0}.el-menu-item{border-radius:10px;margin:5px 0}.el-menu-item.is-active{background:linear-gradient(90deg,#2b9c7a,#42b98e)!important;box-shadow:0 8px 18px rgba(25,165,123,.28)}.aside-foot{position:absolute;bottom:25px;color:#8ea7b9;font-size:11px;display:flex;gap:8px;align-items:center;padding-left:12px}.status-dot{width:7px;height:7px;border-radius:50%;background:#42ce91;box-shadow:0 0 8px #42ce91}main{margin-left:238px;flex:1;transition:.2s}aside.mini+main{margin-left:68px}header{height:72px;background:#fff;display:flex;align-items:center;padding:0 24px;border-bottom:1px solid #edf1f6;position:sticky;top:0;z-index:1}.crumb{margin-left:18px;color:#67778d;font-size:13px}.crumb span{margin:0 9px;color:#c0cad6}.header-right{margin-left:auto;display:flex;align-items:center;gap:18px}.user{display:flex;gap:10px;align-items:center}.user b,.user small{display:block;font-size:12px}.user small{color:#99a4b2;margin-top:3px}.content{min-height:calc(100vh - 72px)}</style>
